import{z as d,x as p,o as r,c as A,q as l,j as n,D as e,d as s,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"分片键与再平衡","description":"","frontmatter":{"title":"分片键与再平衡","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shard-key-rebalance.md","filePath":"cs/shard-key-rebalance.md","lastUpdated":1791413859000}'),B={name:"cs/shard-key-rebalance.md"};function h(c,a,m,D,f,u){const t=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=l('<h1 id="分片键与再平衡" tabindex="-1">分片键与再平衡 <a class="header-anchor" href="#分片键与再平衡" aria-label="Permalink to &quot;分片键与再平衡&quot;">​</a></h1><div class="epigraph"><p>分片键决定行落在哪一故障域；再平衡把键范围从过热节点搬走。选错键，再平衡永远在救热点。</p><footer>—— 据主干 sharding 直觉；DeWitt and Gray 并行库；一致性哈希后课</footer></div><p>复制续在<a href="/cs/replication-lag-rmw">读己之写</a>封口。本课打开分布式数据库：单库分区课已水平切；分片把切放到<strong>多进程多机</strong>，提交与故障域分裂。主干 <a href="/cs/sharding">分片直觉</a> 点到水平切。缺口是键选择与再平衡（rebalance）时的数据搬家与路由。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>键：用户 id 哈希均匀但范围查询打全分片；时间范围利于裁剪但最新分区过热。复合键（租户+时间）折中。缺口是<strong>路由元数据</strong>：谁拥有哪些范围，客户端或协调器查表。再平衡：切范围、拷贝、切流量、删旧——与模式迁移的扩展-收缩同构，加上网络与双写窗口。</p><p>跨分片事务：2PC 或确定性定序，本课不重写协议，只承认键一旦让多数事务跨片，分片失败。</p><p><span class="marginnote">单调主键写入打在最大范围片上，与 IOT 热叶同一病。哈希打散写、毁范围。本课权衡。</span></p><p><span class="marginnote">数字实例：10 个分片、用单调递增的订单号作范围键——几乎全部新写入都落在持有最大范围的 1 个分片上，其余 9 个围观；换成哈希键，每片约摊到十分之一写入，但「查今天所有订单」退化成 10 个分片各查一遍再归并。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先量事务：是否带候选键。再选哈希/范围/目录（lookup）。再平衡尽量在线：新片先跟复制，再改路由，再删。一致性哈希下一课专门减搬家量。</p><p><span class="marginnote">直觉类比：在线再平衡像餐厅高峰期加桌——先摆好新桌并上齐餐具（新分片跟复制补齐数据），再把等位客人引过去（改路由切流量），最后才撤旧桌（删旧副本）。顺序一反，客人就会坐到还没上菜的空位上（读到缺数据）。</span></p><p>二级索引全局 vs 本地：全局索引本身要分片，写放大；本地索引查询可能扫所有片。</p>',12)),(r(),n(i,null,{default:e(()=>[o(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E5%88%86%E7%89%87%E9%94%AE%22%5D%20--%3E%20ROUTE%5B%22%E8%B7%AF%E7%94%B1%E8%A1%A8%22%5D%0A%20%20HOT%5B%22%E7%83%AD%E7%82%B9%E8%8C%83%E5%9B%B4%22%5D%20--%3E%20SPLIT%5B%22%E5%88%87%E5%88%86%E5%B9%B6%E6%8B%B7%E8%B4%9D%22%5D%0A%20%20SPLIT%20--%3E%20CUT%5B%22%E5%88%87%E6%B5%81%E9%87%8F%22%5D%0A%20%20CUT%20--%3E%20DROP%5B%22%E5%88%A0%E6%97%A7%E5%89%AF%E6%9C%AC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"读己之写：跨片更难，会话要记每片 LSN 或只读主片。计划：优化器有「分片裁剪」，无键谓词 scatter-gather 全片，代价像未分区表×N。",-1)),a[5]||(a[5]=E("p",null,"再平衡时约束：唯一性跨片要全局索引或键包含唯一列。",-1)),(r(),n(i,null,{default:e(()=>[o(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%80%89%E5%88%86%E7%89%87%E9%94%AE%E7%AD%96%E7%95%A5%22%5D%20--%3E%20H%5B%22%E5%93%88%E5%B8%8C%E9%94%AE%22%5D%0A%20%20H%20--%3E%20H1%5B%22%E5%86%99%E5%9D%87%E5%8C%80%2C%20%E6%AF%8F%E7%89%87%E7%BA%A6%201%2FN%22%5D%0A%20%20H%20--%3E%20H2%5B%22%E8%8C%83%E5%9B%B4%E6%9F%A5%E8%AF%A2%E6%89%93%E5%85%A8%E9%83%A8%E5%88%86%E7%89%87%22%5D%0A%20%20Q%20--%3E%20R%5B%22%E8%8C%83%E5%9B%B4%E9%94%AE%22%5D%0A%20%20R%20--%3E%20R1%5B%22%E6%97%B6%E9%97%B4%E8%A3%81%E5%89%AA%E9%AB%98%E6%95%88%22%5D%0A%20%20R%20--%3E%20R2%5B%22%E6%9C%80%E6%96%B0%E8%8C%83%E5%9B%B4%E5%86%99%E7%83%AD%E7%82%B9%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E5%A4%8D%E5%90%88%E9%94%AE%3A%20%E7%A7%9F%E6%88%B7%2B%E6%97%B6%E9%97%B4%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E6%8A%98%E4%B8%AD%3A%20%E7%89%87%E9%97%B4%E5%88%86%E6%95%A3%2C%20%E7%89%87%E5%86%85%E6%9C%89%E5%BA%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">常见误区：初学者容易把热点当成「机器不够」，加机器了事。热点来自键的时间局部性与切分方式的冲突——分片键不换，加十台机器，那十台照样闲着看一台冒烟；得改键或改切法。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 shuffle join 算法细节——下一课。也不把分片当 5NF。NewSQL 后课把分片+SQL 打成产品族。</p><p>后课默认：分片键对齐事务边界；再平衡是带路由版本的搬家。shuffle 与 broadcast join：跨片连接如何运数据。</p><p>热点不是硬件不够，是键的时间局部性与切法冲突。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分片键权衡均匀与裁剪；跨片事务比例是失败指标。</li><li>再平衡=拷贝+切路由；元数据要有版本。</li><li>shuffle 与 broadcast join 下一课。</li><li>出处：DeWitt and Gray；主干 sharding；分区课对照。</li></ul>',7))])}const T=d(B,[["render",h]]);export{_ as __pageData,T as default};
